import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            N = int(next(iterator))
            a = [int(next(iterator)) for _ in range(N)]
        except StopIteration:
            break

        if N < 3:
            results.append(" ".join(map(str, a)))
            continue

        diffs = [a[i+1] - a[i] for i in range(N-1)]

        count_d = {}
        for d in diffs:
            count_d[d] = count_d.get(d, 0) + 1

        max_count = 0
        best_d = None
        for d, c in count_d.items():
            if c > max_count:
                max_count = c
                best_d = d

        if max_count == 0:
            pass
        elif max_count == N - 1:
            b = a[:]
        else:
            b = [0] * N
            if max_count >= N - 2:
                b[0] = a[0]
                for i in range(1, N):
                    b[i] = b[i-1] + best_d
            else:
                if best_d is None:
                    b = a[:]
                else:
                    b[0] = a[0]
                    for i in range(1, N):
                        b[i] = b[i-1] + best_d

        mismatches = 0
        for i in range(N):
            if a[i] != b[i]:
                mismatches += 1

        if mismatches > 1:
            if N == 4:
                if abs(a[1]-a[0]) == abs(a[3]-a[2]):
                    d = a[1] - a[0]
                    if a[2] != a[1] + d:
                        b = [a[0], a[1], a[1]+d, a[1]+2*d]
                    else:
                        b = [a[0], a[1], a[a[1]+d], a[3]]
                else:
                    d = a[2] - a[1]
                    b = [a[0], a[1], a[2], a[2]+d]
            else:
                if abs(a[1]-a[0]) == abs((a[N-1]-a[N-2])):
                    d = a[1] - a[0]
                    b = [a[0] + i*d for i in range(N)]
                else:
                    d = a[2] - a[0] / 2 if (a[2] - a[0]) % 2 == 0 else a[1] - a[0]
                    if (a[2] - a[0]) % 2 == (a[3] - a[1]) % 2 and (a[2] - a[0]) // 2 == (a[3] - a[1]) // 2:
                         d = (a[2] - a[0]) // 2
                    else:
                        d = a[1] - a[0]
                    b = []
                    if (a[2] - a[0]) % 1 == 0 and (a[2] - a[0]) % 2 == 2 * ((a[2] - a[0]) // 2):
                        d = (a[2] - a[0]) // 2

                    if abs(a[1] - a[0] - d) < 1e-9 or abs(a[1] - a[0] - d) == 0:
                        start = a[0]
                    else:
                        start = a[1] - d
                    b = [start + i*d for i in range(N)]

                    if mismatches > 1:
                        if abs(a[N-1] - a[N-2]) == abs(a[1] - a[0]):
                            d = a[1] - a[0]
                            b = [a[0] + i*d for i in range(N)][:N]
                        else:
                            d = a[N-1] - a[N-2]
                            start = a[N-1] - (N-1)*d
                            b = [start + i*d for i in range(N)]

        results.append(" ".join(map(str, b)))

    print("\n".join(results))

if __name__ == "__main__":
    solve()
